INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('麻黄汤', '张仲景《伤寒论》', '张仲景', '解表剂', '[{"name": "麻黄", "dose": 9.0, "unit": "g", "role": "君药"}, {"name": "桂枝", "dose": 6.0, "unit": "g", "role": "臣药"}, {"name": "苦杏仁", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "炙甘草", "dose": 3.0, "unit": "g", "role": "使药"}]'::jsonb, '外感风寒表实证。症见恶寒发热、头痛身疼、无汗而喘、脉浮紧。', '麻黄', '桂枝', '苦杏仁', '炙甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('桂枝汤', '张仲景《伤寒论》', '张仲景', '解表剂', '[{"name": "桂枝", "dose": 9.0, "unit": "g", "role": "君药"}, {"name": "白芍", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "生姜", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "大枣", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "炙甘草", "dose": 6.0, "unit": "g", "role": "使药"}]'::jsonb, '外感风寒表虚证。症见头痛发热、汗出恶风、鼻鸣干呕、脉浮缓。', '桂枝', '白芍', '生姜, 大枣', '炙甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('九味羌活汤', '张元素《此事难知》', '张元素', '解表剂', '[{"name": "羌活", "dose": 9.0, "unit": "g", "role": "君药"}, {"name": "防风", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "苍术", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "细辛", "dose": 2.0, "unit": "g", "role": "佐药"}, {"name": "川芎", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "白芷", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "生地黄", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "黄芩", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "甘草", "dose": 3.0, "unit": "g", "role": "使药"}]'::jsonb, '外感风寒湿邪，内有蕴热证。恶寒发热、无汗、头痛项强、肢体酸楚疼痛、口苦微渴。', '羌活', '防风, 苍术', '细辛, 川芎, 白芷, 生地黄, 黄芩', '甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
