INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('银翘散', '吴鞠通《温病条辨》', '吴鞠通', '解表剂', '[{"name": "金银花", "dose": 15.0, "unit": "g", "role": "君药"}, {"name": "连翘", "dose": 15.0, "unit": "g", "role": "君药"}, {"name": "桔梗", "dose": 6.0, "unit": "g", "role": "臣药"}, {"name": "薄荷", "dose": 6.0, "unit": "g", "role": "臣药"}, {"name": "牛蒡子", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "竹叶", "dose": 4.0, "unit": "g", "role": "佐药"}, {"name": "荆芥", "dose": 5.0, "unit": "g", "role": "佐药"}, {"name": "淡豆豉", "dose": 5.0, "unit": "g", "role": "佐药"}, {"name": "芦根", "dose": 10.0, "unit": "g", "role": "佐药"}, {"name": "生甘草", "dose": 4.0, "unit": "g", "role": "使药"}]'::jsonb, '温病初起之表热证。发热无汗、或有汗不畅、微恶风寒、头痛口渴、咽痛咳嗽。', '金银花, 连翘', '桔梗, 薄荷, 牛蒡子', '竹叶, 荆芥, 淡豆豉, 芦根', '生甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
