INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('大承气汤', '张仲景《伤寒论》', '张仲景', '泻下剂', '[{"name": "大黄", "dose": 12.0, "unit": "g", "role": "君药"}, {"name": "芒硝", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "枳实", "dose": 12.0, "unit": "g", "role": "佐药"}, {"name": "厚朴", "dose": 15.0, "unit": "g", "role": "佐药"}]'::jsonb, '阳明腑实证。大便不通、频转矢气、脘腹痞满、腹痛拒按、潮热谵语、手足濈然汗出、脉沉实。', '大黄', '芒硝', '枳实, 厚朴', '无使药(峻下急救)') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
