INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('小柴胡汤', '张仲景《伤寒论》', '张仲景', '和解剂', '[{"name": "柴胡", "dose": 12.0, "unit": "g", "role": "君药"}, {"name": "黄芩", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "半夏", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "生姜", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "人参", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "大枣", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "炙甘草", "dose": 6.0, "unit": "g", "role": "使药"}]'::jsonb, '伤寒少阳病证。往来寒热、胸胁苦满、嘿嘿不欲饮食、心烦喜呕、口苦咽干目眩。', '柴胡', '黄芩', '半夏, 生姜, 人参, 大枣', '炙甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('大柴胡汤', '张仲景《金匮要略》', '张仲景', '和解剂', '[{"name": "柴胡", "dose": 15.0, "unit": "g", "role": "君药"}, {"name": "黄芩", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "大黄", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "枳实", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "芍药", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "半夏", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "生姜", "dose": 15.0, "unit": "g", "role": "佐药"}, {"name": "大枣", "dose": 9.0, "unit": "g", "role": "使药"}]'::jsonb, '少阳阳明合病。往来寒热、胸胁苦满、呕不止、郁郁微烦、心下痞硬、便秘黄疸。', '柴胡', '黄芩', '大黄, 枳实, 芍药, 半夏, 生姜', '大枣') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('逍遥散', '《太平惠民和剂局方》', '局方', '和解剂', '[{"name": "柴胡", "dose": 9.0, "unit": "g", "role": "君药"}, {"name": "当归", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "白芍", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "白术", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "茯苓", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "薄荷", "dose": 3.0, "unit": "g", "role": "佐药"}, {"name": "煨生姜", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "炙甘草", "dose": 4.5, "unit": "g", "role": "使药"}]'::jsonb, '肝郁血虚脾弱证。两胁作痛、头痛目眩、神疲食少、月经不调、乳房胀痛、脉弦而虚。', '柴胡', '当归, 白芍', '白术, 茯苓, 薄荷, 煨生姜', '炙甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('痛泻要方', '朱丹溪《丹溪心法》', '朱丹溪', '和解剂', '[{"name": "白术", "dose": 15.0, "unit": "g", "role": "君药"}, {"name": "白芍", "dose": 12.0, "unit": "g", "role": "臣药"}, {"name": "陈皮", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "防风", "dose": 6.0, "unit": "g", "role": "使药"}]'::jsonb, '脾虚肝旺之痛泻。肠鸣腹痛、大便泄泻、泻必腹痛、泻后痛不减、脉弦缓。', '白术', '白芍', '陈皮', '防风') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('半夏泻心汤', '张仲景《伤寒论》', '张仲景', '和解剂', '[{"name": "半夏", "dose": 12.0, "unit": "g", "role": "君药"}, {"name": "干姜", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "黄芩", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "黄连", "dose": 3.0, "unit": "g", "role": "臣药"}, {"name": "人参", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "大枣", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "炙甘草", "dose": 9.0, "unit": "g", "role": "使药"}]'::jsonb, '寒热互结之痞证。心下痞满而不痛、干呕或呕吐、肠鸣下利、舌苔薄黄而腻。', '半夏', '干姜, 黄芩, 黄连', '人参, 大枣', '炙甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('白虎汤', '张仲景《伤寒论》', '张仲景', '清热剂', '[{"name": "石膏", "dose": 30.0, "unit": "g", "role": "君药"}, {"name": "知母", "dose": 18.0, "unit": "g", "role": "臣药"}, {"name": "粳米", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "炙甘草", "dose": 6.0, "unit": "g", "role": "使药"}]'::jsonb, '阳明气分热盛证。大热、大汗、大渴、脉洪大（四大症）。', '石膏', '知母', '粳米', '炙甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('黄连解毒汤', '王焘《外台秘要》', '王焘', '清热剂', '[{"name": "黄连", "dose": 9.0, "unit": "g", "role": "君药"}, {"name": "黄芩", "dose": 6.0, "unit": "g", "role": "臣药"}, {"name": "黄柏", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "栀子", "dose": 9.0, "unit": "g", "role": "使药"}]'::jsonb, '三焦火毒充斥证。大热烦躁、口燥咽干、目赤口疮、吐血衄血、热毒发斑、舌红苔黄、脉数有力。', '黄连', '黄芩', '黄柏', '栀子') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('龙胆泻肝汤', '李东垣《兰室秘藏》', '李东垣', '清热剂', '[{"name": "龙胆", "dose": 6.0, "unit": "g", "role": "君药"}, {"name": "黄芩", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "栀子", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "泽泻", "dose": 12.0, "unit": "g", "role": "佐药"}, {"name": "木通", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "车前子", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "生地黄", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "当归", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "柴胡", "dose": 6.0, "unit": "g", "role": "使药"}, {"name": "生甘草", "dose": 4.0, "unit": "g", "role": "使药"}]'::jsonb, '肝胆实火上炎，或肝经湿热下注证。头痛目赤、胁痛口苦、耳聋耳肿；阴肿阴痒、带下黄臭、小便淋浊。', '龙胆', '黄芩, 栀子', '泽泻, 木通, 车前子, 生地黄, 当归', '柴胡, 生甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('仙方活命饮', '陈自明《妇人大全良方》', '陈自明', '清热剂', '[{"name": "金银花", "dose": 15.0, "unit": "g", "role": "君药"}, {"name": "陈皮", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "当归", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "防风", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "白芷", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "赤芍", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "贝母", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "天花粉", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "乳香", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "没药", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "甘草", "dose": 6.0, "unit": "g", "role": "使药"}]'::jsonb, '痈疡肿毒初起。热毒壅结，气滞血瘀所致之乳痈、疔疮。红肿焮痛、身热凛寒。', '金银花', '陈皮, 当归', '防风, 白芷, 赤芍, 贝母, 天花粉, 乳香, 没药', '甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('清营汤', '吴鞠通《温病条辨》', '吴鞠通', '清热剂', '[{"name": "水牛角", "dose": 30.0, "unit": "g", "role": "君药"}, {"name": "生地黄", "dose": 15.0, "unit": "g", "role": "臣药"}, {"name": "玄参", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "麦冬", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "金银花", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "连翘", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "黄连", "dose": 4.5, "unit": "g", "role": "佐药"}, {"name": "竹叶", "dose": 3.0, "unit": "g", "role": "佐药"}, {"name": "丹参", "dose": 6.0, "unit": "g", "role": "使药"}]'::jsonb, '邪热传营证。身热夜甚、神烦少寐、时有谵语、斑疹隐隐、舌绛而干、脉细数。', '水牛角', '生地黄, 玄参', '麦冬, 金银花, 连翘, 黄连, 竹叶', '丹参') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('导赤散', '钱乙《小儿药证直诀》', '钱乙', '清热剂', '[{"name": "生地黄", "dose": 15.0, "unit": "g", "role": "君药"}, {"name": "木通", "dose": 6.0, "unit": "g", "role": "臣药"}, {"name": "竹叶", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "生甘草梢", "dose": 6.0, "unit": "g", "role": "使药"}]'::jsonb, '心经火热证。心胸烦热、口渴面赤、口舌生疮、小便赤涩刺痛、舌红脉数。', '生地黄', '木通', '竹叶', '生甘草梢') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('四逆汤', '张仲景《伤寒论》', '张仲景', '温里剂', '[{"name": "附子", "dose": 15.0, "unit": "g", "role": "君药"}, {"name": "干姜", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "炙甘草", "dose": 6.0, "unit": "g", "role": "使药"}]'::jsonb, '心肾阳衰寒厥证。四肢厥逆、神衰欲寐、恶寒蜷卧、下利清谷、舌淡苔白滑、脉微细欲绝。', '附子', '干姜', '无佐药', '炙甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('当归四逆汤', '张仲景《伤寒论》', '张仲景', '温里剂', '[{"name": "当归", "dose": 12.0, "unit": "g", "role": "君药"}, {"name": "桂枝", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "芍药", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "细辛", "dose": 3.0, "unit": "g", "role": "佐药"}, {"name": "通草", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "大枣", "dose": 8.0, "unit": "g", "role": "佐药"}, {"name": "炙甘草", "dose": 6.0, "unit": "g", "role": "使药"}]'::jsonb, '血虚寒厥证。手足厥寒、口不渴、舌淡苔白、脉细欲绝。', '当归', '桂枝, 芍药', '细辛, 通草, 大枣', '炙甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('理中丸', '张仲景《伤寒论》', '张仲景', '温里剂', '[{"name": "干姜", "dose": 9.0, "unit": "g", "role": "君药"}, {"name": "人参", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "白术", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "炙甘草", "dose": 9.0, "unit": "g", "role": "使药"}]'::jsonb, '脾胃虚寒证。自利不渴、呕吐腹痛、腹满不欲食、手足不温、口多涎唾、舌淡苔白、脉沉细。', '干姜', '人参', '白术', '炙甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('吴茱萸汤', '张仲景《伤寒论》', '张仲景', '温里剂', '[{"name": "吴茱萸", "dose": 9.0, "unit": "g", "role": "君药"}, {"name": "人参", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "生姜", "dose": 18.0, "unit": "g", "role": "佐药"}, {"name": "大枣", "dose": 12.0, "unit": "g", "role": "使药"}]'::jsonb, '肝胃虚寒、浊阴上逆证。食后泛泛欲吐、干呕吐涎沫、头痛巅顶、吐利转筋。', '吴茱萸', '人参', '生姜', '大枣') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('四君子汤', '《太平惠民和剂局方》', '局方', '补益剂', '[{"name": "人参", "dose": 9.0, "unit": "g", "role": "君药"}, {"name": "白术", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "茯苓", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "炙甘草", "dose": 6.0, "unit": "g", "role": "使药"}]'::jsonb, '脾胃气虚证。面色萎黄、语声低微、四肢乏力、食少便溏、舌淡苔白、脉虚数。', '人参', '白术', '茯苓', '炙甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('参苓白术散', '《太平惠民和剂局方》', '局方', '补益剂', '[{"name": "莲子肉", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "薏苡仁", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "砂仁", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "桔梗", "dose": 6.0, "unit": "g", "role": "使药"}, {"name": "白扁豆", "dose": 12.0, "unit": "g", "role": "臣药"}, {"name": "白茯苓", "dose": 15.0, "unit": "g", "role": "臣药"}, {"name": "人参", "dose": 15.0, "unit": "g", "role": "君药"}, {"name": "生甘草", "dose": 9.0, "unit": "g", "role": "使药"}, {"name": "白术", "dose": 15.0, "unit": "g", "role": "君药"}, {"name": "山药", "dose": 15.0, "unit": "g", "role": "臣药"}]'::jsonb, '脾虚湿盛证。饮食不消、大便溏泄、胸脘痞闷、四肢无力、形体消瘦、舌淡苔白腻、脉虚缓。', '人参, 白术', '白茯苓, 山药, 白扁豆', '莲子肉, 薏苡仁, 砂仁', '桔梗, 生甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('补中益气汤', '李东垣《脾胃论》', '李东垣', '补益剂', '[{"name": "黄芪", "dose": 15.0, "unit": "g", "role": "君药"}, {"name": "人参", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "白术", "dose": 10.0, "unit": "g", "role": "臣药"}, {"name": "炙甘草", "dose": 6.0, "unit": "g", "role": "使药"}, {"name": "当归", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "陈皮", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "升麻", "dose": 3.0, "unit": "g", "role": "佐药"}, {"name": "柴胡", "dose": 3.0, "unit": "g", "role": "佐药"}]'::jsonb, '脾虚气陷证。体倦乏力、食少腹胀、久泻脱肛、子宫脱垂、气虚发热。', '黄芪', '人参, 白术', '当归, 陈皮, 升麻, 柴胡', '炙甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('生脉散', '李东垣《内外伤辨惑论》', '李东垣', '补益剂', '[{"name": "人参", "dose": 9.0, "unit": "g", "role": "君药"}, {"name": "麦冬", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "五味子", "dose": 6.0, "unit": "g", "role": "佐使药"}]'::jsonb, '温热气阴两伤，或久咳伤肺气阴证。汗多神疲、体倦少气、咽干口渴、干咳少痰、脉虚细数。', '人参', '麦冬', '五味子', '五味子') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('玉屏风散', '朱丹溪《丹溪心法》', '朱丹溪', '补益剂', '[{"name": "黄芪", "dose": 30.0, "unit": "g", "role": "君药"}, {"name": "白术", "dose": 10.0, "unit": "g", "role": "臣药"}, {"name": "防风", "dose": 10.0, "unit": "g", "role": "佐使药"}]'::jsonb, '表虚自汗。自汗恶风、面色㿠白、体虚易感风邪、舌淡苔白、脉浮虚。', '黄芪', '白术', '防风', '防风') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('四物汤', '《太平惠民和剂局方》', '局方', '补益剂', '[{"name": "熟地黄", "dose": 15.0, "unit": "g", "role": "君药"}, {"name": "当归", "dose": 12.0, "unit": "g", "role": "臣药"}, {"name": "白芍", "dose": 10.0, "unit": "g", "role": "佐药"}, {"name": "川芎", "dose": 6.0, "unit": "g", "role": "使药"}]'::jsonb, '营血虚滞证。面色无华、头晕目眩、心悸失眠、唇爪无华、妇人月经不调、量少或经闭、舌淡脉细。', '熟地黄', '当归', '白芍', '川芎') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('当归补血汤', '李东垣《内外伤辨惑论》', '李东垣', '补益剂', '[{"name": "黄芪", "dose": 30.0, "unit": "g", "role": "君药"}, {"name": "当归", "dose": 6.0, "unit": "g", "role": "臣药"}]'::jsonb, '血虚发热证。肌热面赤、烦渴引饮、脉大而虚、重按无力。妇人经期及产后发热。', '黄芪', '当归', '无佐药', '无使药') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('归脾汤', '严用和《济生方》', '严用和', '补益剂', '[{"name": "黄芪", "dose": 12.0, "unit": "g", "role": "君药"}, {"name": "龙眼肉", "dose": 12.0, "unit": "g", "role": "君药"}, {"name": "白术", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "茯神", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "酸枣仁", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "人参", "dose": 6.0, "unit": "g", "role": "臣药"}, {"name": "当归", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "远志", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "木香", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "生姜", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "大枣", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "炙甘草", "dose": 3.0, "unit": "g", "role": "使药"}]'::jsonb, '心脾两虚，气血不足，或脾不统血证。心悸怔忡、失眠健忘、食少神疲、面色萎黄、便血崩漏、月经超前。', '黄芪, 龙眼肉', '白术, 茯神, 酸枣仁, 人参', '当归, 远志, 木香, 生姜, 大枣', '炙甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('六味地黄丸', '钱乙《小儿药证直诀》', '钱乙', '补益剂', '[{"name": "熟地黄", "dose": 24.0, "unit": "g", "role": "君药"}, {"name": "山茱萸", "dose": 12.0, "unit": "g", "role": "臣药"}, {"name": "山药", "dose": 12.0, "unit": "g", "role": "臣药"}, {"name": "茯苓", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "泽泻", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "牡丹皮", "dose": 9.0, "unit": "g", "role": "佐药"}]'::jsonb, '肝肾阴虚证。腰膝酸软、头晕目眩、耳鸣耳聋、盗汗遗精、骨蒸潮热、消渴、小儿囟开不合、舌红少苔、脉沉细数。', '熟地黄', '山茱萸, 山药', '茯苓, 泽泻, 牡丹皮', '无使药(三补三泻)') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('左归丸', '张景岳《景岳全书》', '张景岳', '补益剂', '[{"name": "熟地黄", "dose": 24.0, "unit": "g", "role": "君药"}, {"name": "山药", "dose": 12.0, "unit": "g", "role": "臣药"}, {"name": "枸杞子", "dose": 12.0, "unit": "g", "role": "臣药"}, {"name": "山茱萸", "dose": 12.0, "unit": "g", "role": "臣药"}, {"name": "菟丝子", "dose": 12.0, "unit": "g", "role": "佐药"}, {"name": "鹿角胶", "dose": 12.0, "unit": "g", "role": "佐药"}, {"name": "龟甲胶", "dose": 12.0, "unit": "g", "role": "佐药"}, {"name": "牛膝", "dose": 9.0, "unit": "g", "role": "使药"}]'::jsonb, '真阴不足证。头晕目眩、耳鸣耳聋、腰膝酸软、盗汗自汗、神疲口燥、遗精滑泄、舌光少苔、脉细数。', '熟地黄', '山药, 枸杞子, 山茱萸', '菟丝子, 鹿角胶, 龟甲胶', '牛膝') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('右归丸', '张景岳《景岳全书》', '张景岳', '补益剂', '[{"name": "熟地黄", "dose": 24.0, "unit": "g", "role": "君药"}, {"name": "山药", "dose": 12.0, "unit": "g", "role": "臣药"}, {"name": "山茱萸", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "枸杞子", "dose": 12.0, "unit": "g", "role": "臣药"}, {"name": "菟丝子", "dose": 12.0, "unit": "g", "role": "佐药"}, {"name": "杜仲", "dose": 12.0, "unit": "g", "role": "佐药"}, {"name": "鹿角胶", "dose": 12.0, "unit": "g", "role": "佐药"}, {"name": "当归", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "肉桂", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "制附子", "dose": 6.0, "unit": "g", "role": "佐药"}]'::jsonb, '肾阳不足，命门火衰证。气怯神疲、畏寒肢冷、腰膝软弱、阳痿遗精、大便溏薄、小便清长。', '熟地黄', '山药, 山茱萸, 枸杞子', '菟丝子, 杜仲, 鹿角胶, 当归, 肉桂, 制附子', '无使药') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('柴胡疏肝散', '张景岳《景岳全书》', '张景岳', '理气剂', '[{"name": "柴胡", "dose": 12.0, "unit": "g", "role": "君药"}, {"name": "陈皮", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "川芎", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "香附", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "枳壳", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "芍药", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "炙甘草", "dose": 3.0, "unit": "g", "role": "使药"}]'::jsonb, '肝气郁结证。胁肋疼痛、胸闷善太息、寒热往来、脉弦。', '柴胡', '陈皮, 川芎, 香附', '枳壳, 芍药', '炙甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('越鞠丸', '朱丹溪《丹溪心法》', '朱丹溪', '理气剂', '[{"name": "香附", "dose": 10.0, "unit": "g", "role": "君药"}, {"name": "川芎", "dose": 10.0, "unit": "g", "role": "臣药"}, {"name": "苍术", "dose": 10.0, "unit": "g", "role": "臣药"}, {"name": "栀子", "dose": 10.0, "unit": "g", "role": "佐药"}, {"name": "神曲", "dose": 10.0, "unit": "g", "role": "使药"}]'::jsonb, '六郁证（气、血、痰、火、湿、食郁）。胸膈痞闷、脘腹胀痛、嗳气吞酸、恶心呕吐、饮食不消。', '香附', '川芎, 苍术', '栀子', '神曲') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('血府逐瘀汤', '王清任《医林改错》', '王清任', '活血祛瘀剂', '[{"name": "桃仁", "dose": 12.0, "unit": "g", "role": "君药"}, {"name": "红花", "dose": 9.0, "unit": "g", "role": "君药"}, {"name": "当归", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "生地黄", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "川芎", "dose": 6.0, "unit": "g", "role": "臣药"}, {"name": "赤芍", "dose": 6.0, "unit": "g", "role": "臣药"}, {"name": "牛膝", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "柴胡", "dose": 3.0, "unit": "g", "role": "佐药"}, {"name": "枳壳", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "桔梗", "dose": 4.5, "unit": "g", "role": "佐药"}, {"name": "甘草", "dose": 3.0, "unit": "g", "role": "使药"}]'::jsonb, '胸中血瘀证。胸痛、头痛日久不愈、痛如针刺、内热瞀闷、心悸怔忡、夜不能寐、急躁易怒、舌紫暗或有瘀斑、脉涩。', '桃仁, 红花', '当归, 生地黄, 川芎, 赤芍', '牛膝, 柴胡, 枳壳, 桔梗', '甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('补阳还五汤', '王清任《医林改错》', '王清任', '活血祛瘀剂', '[{"name": "生黄芪", "dose": 60.0, "unit": "g", "role": "君药"}, {"name": "当归尾", "dose": 6.0, "unit": "g", "role": "臣药"}, {"name": "赤芍", "dose": 4.5, "unit": "g", "role": "佐药"}, {"name": "地龙", "dose": 3.0, "unit": "g", "role": "佐药"}, {"name": "川芎", "dose": 3.0, "unit": "g", "role": "佐药"}, {"name": "红花", "dose": 3.0, "unit": "g", "role": "佐药"}, {"name": "桃仁", "dose": 3.0, "unit": "g", "role": "佐药"}]'::jsonb, '中风气虚血瘀证。半身不遂、口眼㖞斜、语言謇涩、口角流涎、小便频数或遗尿不禁、苔白脉缓。', '生黄芪', '当归尾', '赤芍, 地龙, 川芎, 红花, 桃仁', '无使药') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('温经汤', '张仲景《金匮要略》', '张仲景', '活血祛瘀剂', '[{"name": "吴茱萸", "dose": 9.0, "unit": "g", "role": "君药"}, {"name": "桂枝", "dose": 6.0, "unit": "g", "role": "君药"}, {"name": "当归", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "川芎", "dose": 6.0, "unit": "g", "role": "臣药"}, {"name": "芍药", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "丹皮", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "阿胶", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "麦冬", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "人参", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "半夏", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "生姜", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "甘草", "dose": 6.0, "unit": "g", "role": "使药"}]'::jsonb, '冲任虚寒，瘀血阻滞证。漏下不止、月经不调、傍晚发热、手心烦热、唇口干燥、少腹里急腹痛、久不受孕。', '吴茱萸, 桂枝', '当归, 川芎, 芍药', '丹皮, 阿胶, 麦冬, 人参, 半夏, 生姜', '甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('生化汤', '傅山《傅青主女科》', '傅山', '活血祛瘀剂', '[{"name": "全当归", "dose": 24.0, "unit": "g", "role": "君药"}, {"name": "川芎", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "桃仁", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "炮姜", "dose": 2.0, "unit": "g", "role": "佐药"}, {"name": "炙甘草", "dose": 2.0, "unit": "g", "role": "使药"}]'::jsonb, '产后血虚受寒，瘀阻胞宫证。恶露不行或下之不畅、小腹冷痛、舌质紫暗、脉细涩。', '全当归', '川芎', '桃仁, 炮姜', '炙甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('平胃散', '《太平惠民和剂局方》', '局方', '祛湿剂', '[{"name": "苍术", "dose": 12.0, "unit": "g", "role": "君药"}, {"name": "厚朴", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "陈皮", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "生姜", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "大枣", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "炙甘草", "dose": 3.0, "unit": "g", "role": "使药"}]'::jsonb, '湿滞脾胃证。脘腹胀满、不思饮食、口淡无味、恶心呕吐、肢体沉重、大便溏泄、舌苔白腻而厚、脉缓。', '苍术', '厚朴', '陈皮, 生姜, 大枣', '炙甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('藿香正气散', '《太平惠民和剂局方》', '局方', '祛湿剂', '[{"name": "广藿香", "dose": 9.0, "unit": "g", "role": "君药"}, {"name": "紫苏叶", "dose": 3.0, "unit": "g", "role": "臣药"}, {"name": "白芷", "dose": 3.0, "unit": "g", "role": "臣药"}, {"name": "白术", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "茯苓", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "半夏", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "陈皮", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "厚朴", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "大腹皮", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "桔梗", "dose": 6.0, "unit": "g", "role": "使药"}, {"name": "甘草", "dose": 3.0, "unit": "g", "role": "使药"}]'::jsonb, '外感风寒，内伤湿滞证。恶寒发热、头痛昏重、胸膈痞闷、脘腹胀痛、呕吐泄泻、舌苔白腻。', '广藿香', '紫苏叶, 白芷', '白术, 茯苓, 半夏, 陈皮, 厚朴, 大腹皮', '桔梗, 甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('五苓散', '张仲景《伤寒论》', '张仲景', '祛湿剂', '[{"name": "泽泻", "dose": 15.0, "unit": "g", "role": "君药"}, {"name": "茯苓", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "猪苓", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "白术", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "桂枝", "dose": 6.0, "unit": "g", "role": "使药"}]'::jsonb, '蓄水证。小便不利、头痛微热、烦渴欲饮、水入即吐（水逆）；水湿内停之水肿泄泻。', '泽泻', '茯苓, 猪苓', '白术', '桂枝') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('二陈汤', '《太平惠民和剂局方》', '局方', '祛痰剂', '[{"name": "半夏", "dose": 15.0, "unit": "g", "role": "君药"}, {"name": "橘红", "dose": 15.0, "unit": "g", "role": "臣药"}, {"name": "白茯苓", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "生姜", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "炙甘草", "dose": 4.5, "unit": "g", "role": "使药"}]'::jsonb, '湿痰证。咳嗽痰多、色白易咯、恶心呕吐、胸膈痞闷、头晕心悸、舌苔白润或白腻、脉滑。', '半夏', '橘红', '白茯苓, 生姜', '炙甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('温胆汤', '孙思邈《备急千金要方》', '孙思邈', '祛痰剂', '[{"name": "半夏", "dose": 6.0, "unit": "g", "role": "君药"}, {"name": "竹茹", "dose": 6.0, "unit": "g", "role": "臣药"}, {"name": "枳实", "dose": 6.0, "unit": "g", "role": "臣药"}, {"name": "陈皮", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "茯苓", "dose": 5.0, "unit": "g", "role": "佐药"}, {"name": "生姜", "dose": 5.0, "unit": "g", "role": "佐药"}, {"name": "大枣", "dose": 4.0, "unit": "g", "role": "佐药"}, {"name": "甘草", "dose": 3.0, "unit": "g", "role": "使药"}]'::jsonb, '胆郁痰扰证。虚烦不寐、惊悸不宁、触事易惊、胸闷吐涎、舌苔白腻或微黄、脉弦滑。', '半夏', '竹茹, 枳实', '陈皮, 茯苓, 生姜, 大枣', '甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('炙甘草汤', '张仲景《伤寒论》', '张仲景', '补益剂 · 气血双补', '[{"name": "炙甘草", "dose": 12.0, "unit": "g", "role": "君药"}, {"name": "人参", "dose": 6.0, "unit": "g", "role": "臣药"}, {"name": "生地黄", "dose": 30.0, "unit": "g", "role": "臣药"}, {"name": "麦冬", "dose": 10.0, "unit": "g", "role": "臣药"}, {"name": "阿胶", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "麻仁", "dose": 10.0, "unit": "g", "role": "佐药"}, {"name": "生姜", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "桂枝", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "大枣", "dose": 10.0, "unit": "g", "role": "使药"}]'::jsonb, '阴血阳气虚弱，心脉失养证。脉结代、心动悸、虚劳肺痿、干咳无痰、舌光少苔。', '炙甘草', '人参, 生地黄, 麦冬', '阿胶, 麻仁, 生姜, 桂枝', '大枣') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('保和丸', '朱丹溪《丹溪心法》', '朱丹溪', '消食剂', '[{"name": "山楂", "dose": 18.0, "unit": "g", "role": "君药"}, {"name": "神曲", "dose": 12.0, "unit": "g", "role": "臣药"}, {"name": "莱菔子", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "半夏", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "陈皮", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "茯苓", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "连翘", "dose": 6.0, "unit": "g", "role": "使药"}]'::jsonb, '食积内停证。脘腹痞满胀痛、嗳腐吞酸、恶食呕逆、大便泄泻、舌苔厚腻、脉滑。', '山楂', '神曲, 莱菔子', '半夏, 陈皮, 茯苓', '连翘') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('止嗽散', '程国彭《医学心悟》', '程国彭', '止咳化痰剂', '[{"name": "桔梗", "dose": 9.0, "unit": "g", "role": "君药"}, {"name": "荆芥", "dose": 9.0, "unit": "g", "role": "君药"}, {"name": "紫菀", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "百部", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "白前", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "陈皮", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "甘草", "dose": 3.0, "unit": "g", "role": "使药"}]'::jsonb, '风邪犯肺之咳嗽证。咳急喉痒、咯痰不爽、微恶风发热、舌苔薄白、脉浮缓。', '桔梗, 荆芥', '紫菀, 百部, 白前', '陈皮', '甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('清胃散', '李东垣《兰室秘藏》', '李东垣', '清热剂 · 清热泻火', '[{"name": "黄连", "dose": 6.0, "unit": "g", "role": "君药"}, {"name": "生地黄", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "牡丹皮", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "当归", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "升麻", "dose": 9.0, "unit": "g", "role": "使药"}]'::jsonb, '胃火上攻牙痛证。牙齿疼痛、齿龈红肿溃烂溃脓、唇舌颊腮肿痛、口热口臭、舌红苔黄、脉滑数。', '黄连', '生地黄, 牡丹皮', '当归', '升麻') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('阳和汤', '王洪绪《外科证治全生集》', '王洪绪', '温里剂 · 温阳散寒', '[{"name": "熟地黄", "dose": 30.0, "unit": "g", "role": "君药"}, {"name": "鹿角胶", "dose": 9.0, "unit": "g", "role": "臣药"}, {"name": "肉桂", "dose": 3.0, "unit": "g", "role": "佐药"}, {"name": "麻黄", "dose": 2.0, "unit": "g", "role": "佐药"}, {"name": "白芥子", "dose": 6.0, "unit": "g", "role": "佐药"}, {"name": "炮姜炭", "dose": 2.0, "unit": "g", "role": "佐药"}, {"name": "生甘草", "dose": 3.0, "unit": "g", "role": "使药"}]'::jsonb, '阴疽。贴骨疽、流注、鹤膝风等。漫肿无头、皮色不变、酸痛无热、口中不渴、舌淡苔白、脉沉细。', '熟地黄', '鹿角胶', '肉桂, 麻黄, 白芥子, 炮姜炭', '生甘草') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
INSERT INTO tcm_formula_catalog (formula_name, source_book, author, category, composition, indications, monarch_herb, minister_herb, assistant_herb, guide_herb) VALUES ('金匮肾气丸', '张仲景《金匮要略》', '张仲景', '补益剂 · 补阳', '[{"name": "干地黄", "dose": 24.0, "unit": "g", "role": "君药"}, {"name": "山药", "dose": 12.0, "unit": "g", "role": "臣药"}, {"name": "山茱萸", "dose": 12.0, "unit": "g", "role": "臣药"}, {"name": "茯苓", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "泽泻", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "牡丹皮", "dose": 9.0, "unit": "g", "role": "佐药"}, {"name": "桂枝", "dose": 3.0, "unit": "g", "role": "使药"}, {"name": "附子", "dose": 3.0, "unit": "g", "role": "使药"}]'::jsonb, '肾阳不足证。腰痛脚软、下半身常有冷感、少腹拘急、小便不利或小便反多、舌淡而胖、脉沉细。', '干地黄', '山药, 山茱萸', '茯苓, 泽泻, 牡丹皮', '桂枝, 附子') ON CONFLICT (formula_name) DO UPDATE SET composition = EXCLUDED.composition;
